thyrox_toolchain_require_pgvector is a function
thyrox_toolchain_require_pgvector () 
{ 
    local sharedir control major;
    if ! sharedir="$("$THYROX_TOOLCHAIN_PG_CONFIG_BIN" --sharedir 2> /dev/null)" || [[ -z "$sharedir" ]]; then
        echo "thyrox_toolchain: pg_config ('$THYROX_TOOLCHAIN_PG_CONFIG_BIN') no resuelve: no hay servidor PostgreSQL" 1>&2;
        echo "                  al que añadir pgvector. Esta cadena no instala el servidor." 1>&2;
        return 2;
    fi;
    control="$sharedir/extension/vector.control";
    [[ -f "$control" ]] && return 0;
    major="$(thyrox_toolchain_pg_major)" || major="<mayor>";
    if [[ "${THYROX_INSTALL_PGVECTOR:-}" != "1" ]]; then
        echo "thyrox_toolchain: falta pgvector (paquete postgresql-$major-pgvector) y la instalacion es opt-in." 1>&2;
        echo "                  Reintenta con THYROX_INSTALL_PGVECTOR=1." 1>&2;
        echo "                  NO se emite conteo: un cero aqui no distinguiria" 1>&2;
        echo "                  «no hay» de «no pude medir»." 1>&2;
        return 2;
    fi;
    local cmd;
    cmd="$(thyrox_toolchain_pgvector_install_cmd)" || return 2;
    $cmd 1>&2 2>&1 || true;
    if [[ ! -f "$control" ]]; then
        echo "thyrox_toolchain: el instalador termino y '$control' sigue sin existir." 1>&2;
        echo "                  Se re-comprueba la extension, no se lee su exit." 1>&2;
        return 2;
    fi;
    return 0
}
