    thyrox_toolchain_acquire_binary "${THYROX_TOOLCHAIN_IP_BIN:-ip}" THYROX_INSTALL_IPROUTE2 "$THYROX_TOOLCHAIN_IPROUTE2_INSTALL_CMD" iproute2
}

